CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schools (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS classes (id TEXT PRIMARY KEY, name TEXT NOT NULL, size INTEGER NOT NULL, grade TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS teachers (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subjects (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rooms (id TEXT PRIMARY KEY, name TEXT NOT NULL, capacity INTEGER NOT NULL, type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS time_slots (id TEXT PRIMARY KEY, day INTEGER NOT NULL, period INTEGER NOT NULL, label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS course_plans (id TEXT PRIMARY KEY, class_id TEXT NOT NULL, subject_id TEXT NOT NULL, teacher_id TEXT NOT NULL, weekly_periods INTEGER NOT NULL, room_type TEXT, fixed_slot_id TEXT, consecutive INTEGER, locked INTEGER NOT NULL DEFAULT 0);
